-- FlashVision ERP - Supabase New Project Setup Script
-- Project URL: https://zefeylnjghbdeivdsppc.supabase.co
-- Run this in SQL Editor: https://supabase.com/dashboard/project/zefeylnjghbdeivdsppc/sql/new

-- 1. Create erp_state table (Main monolithic ERP state)
CREATE TABLE IF NOT EXISTS public.erp_state (
    id TEXT PRIMARY KEY,
    state_data JSONB NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. Create user_settings table
CREATE TABLE IF NOT EXISTS public.user_settings (
    username TEXT NOT NULL,
    platform TEXT NOT NULL,
    settings_data JSONB NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    PRIMARY KEY (username, platform)
);

-- 3. Create user_sessions table
CREATE TABLE IF NOT EXISTS public.user_sessions (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    username TEXT,
    connection_id TEXT UNIQUE,
    last_active TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),
    device_info TEXT,
    status TEXT
);

-- 4. Create messages table
CREATE TABLE IF NOT EXISTS public.messages (
    id TEXT PRIMARY KEY,
    sender_id TEXT,
    receiver_id TEXT,
    group_id TEXT,
    text TEXT,
    status TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

-- 5. Create call_sessions table
CREATE TABLE IF NOT EXISTS public.call_sessions (
    id TEXT PRIMARY KEY,
    caller_id TEXT,
    receiver_ids TEXT[],
    call_type TEXT,
    status TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

-- 6. Create routing_rules table
CREATE TABLE IF NOT EXISTS public.routing_rules (
    id TEXT PRIMARY KEY,
    rule_name TEXT NOT NULL,
    status TEXT DEFAULT 'Active',
    steps JSONB NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

-- 7. Create routing_tasks table
CREATE TABLE IF NOT EXISTS public.routing_tasks (
    id TEXT PRIMARY KEY,
    rule_id TEXT,
    rule_name TEXT,
    document JSONB NOT NULL,
    current_step_index INT DEFAULT 0,
    status TEXT DEFAULT 'Running',
    steps JSONB NOT NULL,
    history JSONB NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

-- 8. Create print_layout_settings table
CREATE TABLE IF NOT EXISTS public.print_layout_settings (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    tenant_id TEXT DEFAULT 'default_tenant',
    document_type TEXT NOT NULL,
    layout_config JSONB NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 9. Standalone Relational Mirror Tables
CREATE TABLE IF NOT EXISTS public.hr_employees (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    department TEXT,
    designation TEXT,
    phone TEXT,
    email TEXT,
    basic_salary NUMERIC DEFAULT 0,
    allowance NUMERIC DEFAULT 0,
    advance NUMERIC DEFAULT 0,
    avatar TEXT,
    status TEXT DEFAULT 'Active'
);

CREATE TABLE IF NOT EXISTS public.hr_overtime_requests (
    id TEXT PRIMARY KEY,
    employee_id TEXT,
    employee_name TEXT,
    date TEXT,
    start_time TEXT,
    end_time TEXT,
    total_hours NUMERIC DEFAULT 0,
    reason TEXT,
    status TEXT DEFAULT 'Pending',
    approved_by TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.hr_loan_requests (
    id TEXT PRIMARY KEY,
    employee_id TEXT,
    employee_name TEXT,
    amount NUMERIC DEFAULT 0,
    installments INT DEFAULT 1,
    monthly_deduction NUMERIC DEFAULT 0,
    status TEXT DEFAULT 'Pending',
    approved_by TEXT,
    reason TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.hr_loan_ledger (
    id TEXT PRIMARY KEY,
    loan_id TEXT,
    employee_id TEXT,
    date TEXT,
    type TEXT,
    amount NUMERIC DEFAULT 0,
    balance NUMERIC DEFAULT 0,
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.approvals (
    id TEXT PRIMARY KEY,
    type TEXT,
    title TEXT,
    requester TEXT,
    status TEXT DEFAULT 'Pending',
    details JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.sale_orders (
    id TEXT PRIMARY KEY,
    order_no TEXT,
    customer_name TEXT,
    total_amount NUMERIC DEFAULT 0,
    status TEXT,
    order_data JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.customers (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    phone TEXT,
    email TEXT,
    balance NUMERIC DEFAULT 0,
    details JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.suppliers (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    phone TEXT,
    email TEXT,
    balance NUMERIC DEFAULT 0,
    details JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.production_plans (
    id TEXT PRIMARY KEY,
    plan_no TEXT,
    status TEXT,
    details JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.users (
    id TEXT PRIMARY KEY,
    username TEXT NOT NULL,
    name TEXT,
    role TEXT,
    permissions JSONB,
    granular_permissions JSONB
);

-- 10. Disable Row Level Security (RLS) for open read/write access
ALTER TABLE public.erp_state DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_settings DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_sessions DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.messages DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.call_sessions DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.routing_rules DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.routing_tasks DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.print_layout_settings DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.hr_employees DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.hr_overtime_requests DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.hr_loan_requests DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.hr_loan_ledger DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.approvals DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.sale_orders DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.customers DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.suppliers DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.production_plans DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.users DISABLE ROW LEVEL SECURITY;

-- 11. Realtime Publication
ALTER PUBLICATION supabase_realtime ADD TABLE 
    public.erp_state, 
    public.user_settings, 
    public.user_sessions, 
    public.messages, 
    public.call_sessions, 
    public.routing_rules, 
    public.routing_tasks,
    public.print_layout_settings;

-- 12. Full Payload Broadcasting
ALTER TABLE public.erp_state REPLICA IDENTITY FULL;
ALTER TABLE public.user_settings REPLICA IDENTITY FULL;
ALTER TABLE public.user_sessions REPLICA IDENTITY FULL;
ALTER TABLE public.messages REPLICA IDENTITY FULL;
ALTER TABLE public.call_sessions REPLICA IDENTITY FULL;
ALTER TABLE public.routing_rules REPLICA IDENTITY FULL;
ALTER TABLE public.routing_tasks REPLICA IDENTITY FULL;

-- 13. High Performance Indexes
CREATE INDEX IF NOT EXISTS idx_erp_state_jsonb ON public.erp_state USING GIN (state_data);
CREATE INDEX IF NOT EXISTS idx_messages_sender ON public.messages(sender_id);
CREATE INDEX IF NOT EXISTS idx_messages_receiver ON public.messages(receiver_id);

